targets.expr:
count by (statefulset, version, image_tag) (
  max by (namespace, pod, statefulset, version) (
    label_replace(
      vg_feature_server_freeswitch_version_info{cluster="$cluster"},
      "statefulset", "$1", "pod", "(.+)-[0-9]+"
    )
  )
  * on (namespace, pod) group_left(image_tag)
  max by (namespace, pod, image_tag) (
    label_replace(
      kube_pod_container_info{cluster="$cluster", container="freeswitch"},
      "image_tag", "$1", "image", ".*:(.+)"
    )
  )
)
